def grade(score, total):
    for letter, need in [("A", 90), ("B", 70), ("C", 50)]:
        if score * 100 >= need * total:
            return letter
    return "F"

letters = []
for n in range(int(input())):
    letters.append(grade(int(input()), int(input())))
for letter in letters:
    print(letter)
print(letters.count("A"))
